"""FastAPI app factory. Routes close over the AppContext — no module globals."""
from __future__ import annotations

import asyncio
import csv
import io
import json
from dataclasses import asdict
from pathlib import Path

from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import JSONResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles

from ..app import MANUAL_BOT_ID, AppContext
from ..models import OrderRequest
from ..signals.conviction import market_conviction
from . import events

FRONTEND_DIR = Path(__file__).resolve().parent.parent.parent / "frontend"
WS_PUSH_INTERVAL_S = 2.0


def create_app(ctx: AppContext) -> FastAPI:
    app = FastAPI(title="CryptoDeck", docs_url=None, redoc_url=None)

    @app.on_event("startup")
    async def _startup():
        await ctx.start()
        events.log_event("info", "system", "CryptoDeck started — PAPER TRADING ONLY")

    @app.on_event("shutdown")
    async def _shutdown():
        await ctx.stop()

    # -- state assembly ---------------------------------------------------------

    def overview_state() -> dict:
        boards = ctx.portfolio.leaderboard()
        runner_status = {r.strategy.name: r.status() for r in ctx.runners.values()}
        return {
            "paper": True,
            "ai_enabled": ctx.analyst.enabled,
            "fear_greed": ctx.fng.latest(),
            "majors": ctx.hub.get_majors(),
            "watchlist": ctx.hub.get_watchlist(),
            "wallets": [asdict(s) | {"win_rate": s.win_rate,
                                     "runner": runner_status.get(s.bot_id)}
                        for s in boards],
            "signals": ctx.db.recent_signals(n=15),
            "alerts": ctx.db.recent_alerts(10),
            "events": events.get_events(40),
            "data_health": ctx.hub.last_poll,
        }

    def position_dict(p) -> dict:
        coin = ctx.db.get_coin(p.coin_id)
        d = asdict(p)
        d["symbol"] = coin.symbol if coin else "?"
        d["value_usd"] = p.value_usd
        d["unrealized_pnl_usd"] = p.unrealized_pnl_usd
        return d

    # -- REST ---------------------------------------------------------------

    @app.get("/api/overview")
    async def overview():
        return overview_state()

    @app.get("/api/conviction")
    async def conviction():
        # deliberately NOT part of overview_state()/the 2s WS push — this scans
        # the signals table + recomputes RSI per watched coin, meaningfully
        # heavier than the push loop, and the underlying signals only change
        # on 30-60min cooldowns anyway. Polled by the client every ~15s instead.
        coins = ctx.db.list_coins(watch_only=True)
        return market_conviction(ctx.db, coins, ctx.fng.latest())

    @app.get("/api/coins")
    async def coins(watch: int = 0):
        return [asdict(c) for c in ctx.db.list_coins(watch_only=bool(watch))]

    @app.get("/api/coins/{coin_id}")
    async def coin_detail(coin_id: int, hours: float = 24):
        coin = ctx.db.get_coin(coin_id)
        if coin is None:
            return JSONResponse({"error": "unknown coin"}, status_code=404)
        quote = ctx.hub.get_quote(coin_id)
        positions = [position_dict(p) for p in ctx.db.open_positions()
                     if p.coin_id == coin_id]
        trades = list(ctx.db.conn.execute(
            "SELECT t.ts, t.side, t.price, t.qty, t.realized_pnl_usd, w.bot_id "
            "FROM trades t JOIN wallets w ON w.id=t.wallet_id "
            "WHERE t.coin_id=? ORDER BY t.ts DESC LIMIT 100", (coin_id,)))
        return {
            "coin": asdict(coin),
            "quote": asdict(quote) if quote else None,
            "history": ctx.hub.price_history(coin_id, hours),
            "positions": positions,
            "trades": trades,
        }

    @app.post("/api/trade")
    async def trade(payload: dict):
        bot_id = payload.get("bot_id", MANUAL_BOT_ID)
        wallet = ctx.db.get_wallet(bot_id)
        if wallet is None:
            return JSONResponse({"error": f"unknown bot '{bot_id}'"}, status_code=400)
        try:
            req = OrderRequest(
                wallet_id=wallet.id,
                coin_id=int(payload["coin_id"]),
                side=payload["side"],
                quote_amount=(float(payload["usd"]) if payload.get("usd") else None),
                qty=(float(payload["qty"]) if payload.get("qty") else None),
            )
        except (KeyError, ValueError) as e:
            return JSONResponse({"error": f"bad request: {e}"}, status_code=400)
        if req.side not in ("buy", "sell"):
            return JSONResponse({"error": "side must be buy or sell"}, status_code=400)
        result = await ctx.exchange.execute(req)
        coin = ctx.db.get_coin(req.coin_id)
        symbol = coin.symbol if coin else "?"
        if result.filled:
            events.log_event("trade", bot_id,
                             f"{req.side.upper()} {symbol}: {result.qty:.6g} @ "
                             f"${result.fill_price:,.6g} (fee ${result.fee_usd:.2f})",
                             req.coin_id)
        else:
            events.log_event("reject", bot_id,
                             f"{req.side.upper()} {symbol} rejected: {result.reject_reason}",
                             req.coin_id)
        return asdict(result)

    @app.post("/api/positions/{position_id}/close")
    async def close_position(position_id: int):
        pos = ctx.db.get_position(position_id)
        if pos is None or pos.status not in ("open", "stale"):
            return JSONResponse({"error": "no open position"}, status_code=404)
        wallet = ctx.db.get_wallet_by_id(pos.wallet_id)
        result = await ctx.exchange.execute(OrderRequest(
            wallet_id=pos.wallet_id, coin_id=pos.coin_id, side="sell", qty=pos.qty))
        if not result.filled:
            attempts = ctx.portfolio.bump_close_attempts(position_id)
            if attempts >= ctx.cfg.max_close_attempts:
                ctx.portfolio.mark_stale(position_id)
                ctx.db.add_alert("warning", "exchange", coin_id=pos.coin_id,
                                 message=f"Position {position_id} unsellable after "
                                         f"{attempts} attempts — marked stale. "
                                         f"Use write-off to close it at $0.")
        return asdict(result)

    @app.post("/api/positions/{position_id}/write-off")
    async def write_off(position_id: int):
        pos = ctx.db.get_position(position_id)
        if pos is None or pos.status not in ("open", "stale"):
            return JSONResponse({"error": "no open position"}, status_code=404)
        ctx.portfolio.write_off(position_id)
        events.log_event("info", "portfolio",
                         f"Position {position_id} written off at $0", pos.coin_id)
        return {"ok": True}

    @app.get("/api/bots/{bot_id}")
    async def bot_detail(bot_id: str):
        wallet = ctx.db.get_wallet(bot_id)
        if wallet is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        s = ctx.portfolio.stats(wallet)
        return {
            "stats": asdict(s) | {"win_rate": s.win_rate},
            "positions": [position_dict(p)
                          for p in ctx.db.positions_for_wallet(wallet.id)],
            "trades": ctx.db.trades_for_wallet(wallet.id),
            "equity": ctx.db.equity_history(wallet.id),
        }

    @app.get("/api/alerts")
    async def alerts(n: int = 50):
        return ctx.db.recent_alerts(n)

    # -- search / watchlist (M3) ------------------------------------------------

    @app.get("/api/search")
    async def search(q: str):
        if not q or len(q) < 2:
            return []
        return await ctx.hub.search_token(q)

    @app.post("/api/coins/watch")
    async def watch_coin(payload: dict):
        try:
            coin = ctx.hub.ensure_watched(
                source_id=payload["source_id"], symbol=payload["symbol"],
                name=payload.get("name", payload["symbol"]), chain=payload["chain"])
        except KeyError as e:
            return JSONResponse({"error": f"missing field {e}"}, status_code=400)
        events.log_event("info", "watchlist", f"Watching {coin.symbol} ({coin.chain})")
        return asdict(coin)

    @app.post("/api/coins/{coin_id}/unwatch")
    async def unwatch_coin(coin_id: int):
        ctx.db.set_watch(coin_id, False)
        return {"ok": True}

    # -- bots (M4) ---------------------------------------------------------------

    @app.get("/api/bots")
    async def bots():
        out = []
        for runner in ctx.runners.values():
            wallet = ctx.db.get_wallet(runner.strategy.name)
            s = ctx.portfolio.stats(wallet)
            out.append(runner.status() | {"stats": asdict(s) | {"win_rate": s.win_rate}})
        return out

    @app.post("/api/bots/{bot_id}/pause")
    async def pause_bot(bot_id: str):
        runner = ctx.runners.get(bot_id)
        if runner is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        runner.pause()
        return runner.status()

    @app.post("/api/bots/{bot_id}/resume")
    async def resume_bot(bot_id: str):
        runner = ctx.runners.get(bot_id)
        if runner is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        runner.resume()
        return runner.status()

    @app.get("/api/allocator/weights")
    async def allocator_weights():
        return json.loads(ctx.db.get_setting("bot.apex_allocator.weights", "{}"))

    # -- signals (M5) --------------------------------------------------------------

    @app.get("/api/signals")
    async def signals(coin_id: int | None = None, n: int = 50):
        return ctx.db.recent_signals(coin_id, n)

    # -- AI analyst (M6) ---------------------------------------------------------

    @app.post("/api/analyze/coin/{coin_id}")
    async def analyze_coin(coin_id: int):
        if not ctx.analyst.enabled:
            return JSONResponse({"error": "AI analyst disabled — set ANTHROPIC_API_KEY"},
                                status_code=400)
        coin = ctx.db.get_coin(coin_id)
        if coin is None:
            return JSONResponse({"error": "unknown coin"}, status_code=404)
        report = await ctx.analyst.analyze_coin(coin)
        if report is None:
            return JSONResponse({"error": "analysis failed or budget exhausted "
                                          "(see alerts)"}, status_code=502)
        return report

    @app.post("/api/analyze/market")
    async def analyze_market():
        if not ctx.analyst.enabled:
            return JSONResponse({"error": "AI analyst disabled — set ANTHROPIC_API_KEY"},
                                status_code=400)
        report = await ctx.analyst.market_summary()
        if report is None:
            return JSONResponse({"error": "analysis failed or budget exhausted "
                                          "(see alerts)"}, status_code=502)
        return report

    @app.get("/api/analyses")
    async def analyses(coin_id: int | None = None, n: int = 10):
        if coin_id is not None:
            return list(ctx.db.conn.execute(
                "SELECT * FROM analyses WHERE coin_id=? ORDER BY ts DESC LIMIT ?",
                (coin_id, n)))
        return list(ctx.db.conn.execute(
            "SELECT * FROM analyses ORDER BY ts DESC LIMIT ?", (n,)))

    # -- candlestick bot vision -----------------------------------------------------

    @app.get("/api/candlestick/vision")
    async def candlestick_vision(tf: str = "30m"):
        """What a candlestick bot sees right now: candles, patterns, verdicts."""
        import time as _time
        from ..signals.candles import (build_candles, closed_candles,
                                       detect_patterns, trend_of)
        from ..strategies.candlestick_trader import (BULLISH_ENTRIES,
                                                     CandlestickTrader,
                                                     CandlestickTrader4h)
        strat = CandlestickTrader4h if tf == "4h" else CandlestickTrader
        p = strat.default_params
        bucket = float(p["bucket_s"])
        out = []
        for m in ctx.hub.get_majors():
            coin = ctx.db.get_coin(m["coin_id"])
            if coin is None:
                continue
            history = ctx.db.snapshot_history(coin.id, hours=float(p["history_hours"]))
            all_candles = build_candles(history, bucket)
            # detect on CLOSED candles only — same rule the bot trades by
            candles = closed_candles(all_candles, _time.time(), bucket)
            hits = detect_patterns(candles) if len(candles) >= 3 else []
            entry_hits = [h for h in hits if h.name in BULLISH_ENTRIES
                          and h.strength >= p["min_pattern_strength"]]
            if len(candles) < 12:
                verdict = f"collecting candles ({len(candles)}/12)"
            elif entry_hits:
                verdict = f"BUY SETUP: {entry_hits[0].name}"
            elif hits and hits[0].direction != "neutral":
                verdict = (f"sees {hits[0].name} ({hits[0].direction} "
                           f"{hits[0].strength:.2f}) — "
                           + ("not a bullish entry pattern"
                              if hits[0].direction == "bearish"
                              else f"below strength gate {p['min_pattern_strength']}"))
            elif hits:
                verdict = f"only {hits[0].name} (neutral) — waiting"
            else:
                verdict = "no pattern on current candle — waiting"
            out.append({
                "coin_id": coin.id, "symbol": coin.symbol,
                "trend": trend_of(candles) if candles else "flat",
                "candles": [{"ts": c.ts, "o": c.open, "h": c.high,
                             "l": c.low, "c": c.close} for c in all_candles[-30:]],
                "patterns": [{"name": h.name, "direction": h.direction,
                              "strength": h.strength} for h in hits[:3]],
                "verdict": verdict,
            })
        return out

    # -- backtesting --------------------------------------------------------------

    @app.get("/api/backtest/strategies")
    async def backtest_strategies():
        from ..sweep import SWEEP_GRIDS
        return [{"name": s.name, "description": s.description,
                 "sweep_grid": s.name in SWEEP_GRIDS}
                for s in ctx.backtester.strategies.values()]

    @app.post("/api/backtest")
    async def run_backtest(payload: dict):
        strategy = payload.get("strategy", "")
        hours = float(payload.get("hours", 24))
        result = await asyncio.to_thread(ctx.backtester.run, strategy, hours)
        if "error" in result:
            return JSONResponse(result, status_code=400)
        return result

    @app.post("/api/backtest/sweep")
    async def start_sweep(payload: dict):
        strategy = payload.get("strategy", "")
        hours = float(payload.get("hours", 24))
        result = ctx.sweep.start(strategy, hours)
        if "error" in result:
            return JSONResponse(result, status_code=400)
        asyncio.create_task(ctx.sweep.run_job(result["job_id"]))
        return result

    @app.get("/api/backtest/sweep/{job_id}")
    async def sweep_status(job_id: str):
        result = ctx.sweep.status(job_id)
        if "error" in result:
            return JSONResponse(result, status_code=404)
        return result

    # -- journal --------------------------------------------------------------

    @app.get("/api/journal/{bot_id}")
    async def journal(bot_id: str):
        wallet = ctx.db.get_wallet(bot_id)
        if wallet is None:
            return JSONResponse({"error": "unknown bot"}, status_code=404)
        return ctx.portfolio.journal(wallet)

    # -- morning briefing ----------------------------------------------------------

    @app.get("/api/briefing/latest")
    async def briefing_latest():
        row = ctx.briefing.latest()
        return row or JSONResponse({"error": "no briefing yet"}, status_code=404)

    @app.post("/api/briefing/generate")
    async def briefing_generate():
        return await ctx.briefing.generate()

    # -- price alerts -----------------------------------------------------------

    @app.get("/api/price-alerts")
    async def price_alerts(coin_id: int | None = None):
        return ctx.db.list_price_alerts(coin_id)

    @app.post("/api/price-alerts")
    async def add_price_alert(payload: dict):
        try:
            coin_id = int(payload["coin_id"])
            direction = payload["direction"]
            threshold = float(payload["threshold"])
        except (KeyError, ValueError) as e:
            return JSONResponse({"error": f"bad request: {e}"}, status_code=400)
        if direction not in ("above", "below") or threshold <= 0:
            return JSONResponse({"error": "direction above|below, threshold > 0"},
                                status_code=400)
        if ctx.db.get_coin(coin_id) is None:
            return JSONResponse({"error": "unknown coin"}, status_code=404)
        return ctx.db.add_price_alert(coin_id, direction, threshold)

    @app.post("/api/price-alerts/{alert_id}/delete")
    async def delete_price_alert(alert_id: int):
        ctx.db.delete_price_alert(alert_id)
        return {"ok": True}

    # -- settings (M7) -----------------------------------------------------------

    @app.get("/api/settings")
    async def get_settings():
        from ..config import TUNABLE
        return {
            "values": {k: getattr(ctx.cfg, k) for k in TUNABLE},
            "types": {k: t.__name__ for k, t in TUNABLE.items()},
            "note": "Saved values apply after a restart.",
        }

    @app.post("/api/settings")
    async def set_settings(payload: dict):
        from ..config import TUNABLE
        saved = []
        for key, value in payload.items():
            if key not in TUNABLE:
                continue
            ctx.db.set_setting(f"cfg.{key}", str(value))
            saved.append(key)
        return {"saved": saved, "note": "Restart CryptoDeck to apply."}

    @app.get("/api/export/trades.csv")
    async def export_trades():
        rows = ctx.db.all_trades()
        buf = io.StringIO()
        if rows:
            w = csv.DictWriter(buf, fieldnames=rows[0].keys())
            w.writeheader()
            w.writerows(rows)
        return StreamingResponse(iter([buf.getvalue()]), media_type="text/csv",
                                 headers={"Content-Disposition":
                                          "attachment; filename=trades.csv"})

    # -- WebSocket ---------------------------------------------------------

    @app.websocket("/ws")
    async def ws(sock: WebSocket):
        await sock.accept()
        try:
            while True:
                await sock.send_text(json.dumps(overview_state(), default=str))
                await asyncio.sleep(WS_PUSH_INTERVAL_S)
        except (WebSocketDisconnect, ConnectionError):
            pass

    app.mount("/", StaticFiles(directory=FRONTEND_DIR, html=True), name="frontend")
    return app

