"""Crypto Fear & Greed index — free public API (alternative.me), polled hourly.
Latest value stored in the settings table as JSON; no key required.
"""
from __future__ import annotations

import asyncio
import json
import time

import httpx

from ..db import Database

API_URL = "https://api.alternative.me/fng/?limit=1"
POLL_S = 3600
SETTING_KEY = "fng.latest"


def parse_fng(payload: dict | None) -> dict | None:
    """Extract {value, classification, ts} from the API shape; None if malformed."""
    try:
        row = payload["data"][0]
        return {
            "value": int(row["value"]),
            "classification": row["value_classification"],
            "ts": int(row.get("timestamp") or time.time()),
        }
    except (TypeError, KeyError, IndexError, ValueError):
        return None


class FearGreedPoller:
    def __init__(self, db: Database):
        self.db = db
        self._task: asyncio.Task | None = None

    def latest(self) -> dict | None:
        raw = self.db.get_setting(SETTING_KEY)
        if not raw:
            return None
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return None

    async def start(self) -> None:
        self._task = asyncio.create_task(self._loop())

    async def stop(self) -> None:
        if self._task:
            self._task.cancel()
            await asyncio.gather(self._task, return_exceptions=True)

    async def poll_once(self) -> dict | None:
        try:
            async with httpx.AsyncClient(timeout=15) as http:
                resp = await http.get(API_URL)
                data = parse_fng(resp.json()) if resp.status_code == 200 else None
        except Exception:
            data = None
        if data:
            data["fetched_at"] = time.time()
            self.db.set_setting(SETTING_KEY, json.dumps(data))
        return data

    async def _loop(self) -> None:
        while True:
            await self.poll_once()
            await asyncio.sleep(POLL_S)

cryptodeck/signals/candles.py:
"""Candlestick pattern engine — the Candlestick Trading Bible in code.

Builds OHLC candles from stored price snapshots and detects the book's
patterns (docs/The Candlestick Trading Bible.pdf): engulfing bars, doji
(incl. dragonfly & gravestone), hammer / pin bar, shooting star, morning &
evening stars, harami, tweezers, inside bars. Patterns are read in trend
context, as the book teaches: a hammer only means reversal after a downtrend.
"""
from __future__ import annotations

from dataclasses import dataclass

from ..models import Coin, Quote
from .rules import Rule, SignalHit

DEFAULT_BUCKET_S = 1800  # 30-minute candles


@dataclass(frozen=True)
class Candle:
    ts: float
    open: float
    high: float
    low: float
    close: float

    @property
    def body(self) -> float:
        return abs(self.close - self.open)

    @property
    def range(self) -> float:
        return self.high - self.low

    @property
    def bullish(self) -> bool:
        return self.close > self.open

    @property
    def bearish(self) -> bool:
        return self.close < self.open

    @property
    def upper_shadow(self) -> float:
        return self.high - max(self.open, self.close)

    @property
    def lower_shadow(self) -> float:
        return min(self.open, self.close) - self.low


@dataclass(frozen=True)
class PatternHit:
    name: str
    direction: str      # bullish | bearish | neutral
    strength: float     # 0..1
    candle_low: float   # the book's stop-loss anchor: beyond the pattern
    candle_high: float


def closed_candles(candles: list[Candle], now: float,
                   bucket_s: float = DEFAULT_BUCKET_S) -> list[Candle]:
    """Drop the still-forming candle — the book: act only on the candle CLOSE."""
    if candles and candles[-1].ts + bucket_s > now:
        return candles[:-1]
    return candles


def build_candles(history: list[dict], bucket_s: float = DEFAULT_BUCKET_S) -> list[Candle]:
    """OHLC candles from (ts, price_usd) snapshots, oldest first."""
    buckets: dict[int, list[tuple[float, float]]] = {}
    for h in history:
        buckets.setdefault(int(h["ts"] // bucket_s), []).append((h["ts"], h["price_usd"]))
    candles = []
    for key in sorted(buckets):
        pts = sorted(buckets[key])
        prices = [p for _, p in pts]
        candles.append(Candle(ts=key * bucket_s, open=prices[0], high=max(prices),
                              low=min(prices), close=prices[-1]))
    return candles


def trend_of(candles: list[Candle], lookback: int = 10) -> str:
    """'up' / 'down' / 'flat' from close vs SMA of the preceding candles."""
    if len(candles) < lookback + 1:
        return "flat"
    window = candles[-(lookback + 1):-1]
    sma = sum(c.close for c in window) / len(window)
    last = candles[-2].close if len(candles) >= 2 else candles[-1].close
    if sma <= 0:
        return "flat"
    dev = (last - sma) / sma
    if dev > 0.002:
        return "up"
    if dev < -0.002:
        return "down"
    return "flat"


# -- individual detectors (operate on the last closed candles) -------------------

def _ctx(trend: str, needs: str, strong: float, weak: float = 0.4) -> float:
    """The book's context rule: a reversal pattern only counts after a trend
    in the opposite direction. Wrong context → weak (below every trade
    threshold), so context-less patterns never trigger entries or exits."""
    return strong if trend == needs else weak


def _doji(c: Candle, trend: str) -> PatternHit | None:
    if c.range <= 0 or c.body > c.range * 0.1:
        return None
    if c.lower_shadow >= c.range * 0.6 and c.upper_shadow <= c.range * 0.1:
        return PatternHit("dragonfly_doji", "bullish",
                          _ctx(trend, "down", 0.5, 0.35), c.low, c.high)
    if c.upper_shadow >= c.range * 0.6 and c.lower_shadow <= c.range * 0.1:
        return PatternHit("gravestone_doji", "bearish",
                          _ctx(trend, "up", 0.5, 0.35), c.low, c.high)
    return PatternHit("doji", "neutral", 0.3, c.low, c.high)


def _hammer_star(c: Candle, trend: str) -> PatternHit | None:
    if c.range <= 0 or c.body == 0:
        return None
    # hammer / bullish pin bar: long lower wick, small upper wick
    if c.lower_shadow >= 2 * c.body and c.upper_shadow <= c.body:
        return PatternHit("hammer", "bullish", _ctx(trend, "down", 0.75),
                          c.low, c.high)
    # shooting star / bearish pin bar
    if c.upper_shadow >= 2 * c.body and c.lower_shadow <= c.body:
        return PatternHit("shooting_star", "bearish", _ctx(trend, "up", 0.75),
                          c.low, c.high)
    return None


def _engulfing(prev: Candle, cur: Candle, trend: str) -> PatternHit | None:
    if prev.body == 0 or cur.body == 0:
        return None
    if (prev.bearish and cur.bullish and cur.open <= prev.close
            and cur.close >= prev.open):
        return PatternHit("bullish_engulfing", "bullish", _ctx(trend, "down", 0.7),
                          min(cur.low, prev.low), cur.high)
    if (prev.bullish and cur.bearish and cur.open >= prev.close
            and cur.close <= prev.open):
        return PatternHit("bearish_engulfing", "bearish", _ctx(trend, "up", 0.7),
                          cur.low, max(cur.high, prev.high))
    return None


def _harami(prev: Candle, cur: Candle, trend: str) -> PatternHit | None:
    if prev.body == 0 or cur.body > prev.body * 0.6:
        return None
    inside = (max(cur.open, cur.close) <= max(prev.open, prev.close)
              and min(cur.open, cur.close) >= min(prev.open, prev.close))
    if not inside:
        return None
    if prev.bearish and cur.bullish:
        return PatternHit("bullish_harami", "bullish", _ctx(trend, "down", 0.5),
                          prev.low, prev.high)
    if prev.bullish and cur.bearish:
        return PatternHit("bearish_harami", "bearish", _ctx(trend, "up", 0.5),
                          prev.low, prev.high)
    return None


def _inside_bar(prev: Candle, cur: Candle) -> PatternHit | None:
    if cur.high < prev.high and cur.low > prev.low:
        return PatternHit("inside_bar", "neutral", 0.35, prev.low, prev.high)
    return None


def _tweezers(prev: Candle, cur: Candle, trend: str) -> PatternHit | None:
    if prev.range <= 0:
        return None
    tol = max(prev.range * 0.15, prev.close * 0.0005)
    if abs(prev.low - cur.low) <= tol and prev.bearish and cur.bullish:
        return PatternHit("tweezer_bottom", "bullish", _ctx(trend, "down", 0.55),
                          min(prev.low, cur.low), cur.high)
    if abs(prev.high - cur.high) <= tol and prev.bullish and cur.bearish:
        return PatternHit("tweezer_top", "bearish", _ctx(trend, "up", 0.55),
                          cur.low, max(prev.high, cur.high))
    return None


def _star(a: Candle, b: Candle, c: Candle, trend: str) -> PatternHit | None:
    """Morning / evening star: big move, indecision, strong reversal."""
    if a.body == 0 or c.body == 0 or b.body > a.body * 0.5:
        return None
    midpoint_a = (a.open + a.close) / 2
    if a.bearish and c.bullish and c.close > midpoint_a:
        return PatternHit("morning_star", "bullish", _ctx(trend, "down", 0.8),
                          min(a.low, b.low, c.low), c.high)
    if a.bullish and c.bearish and c.close < midpoint_a:
        return PatternHit("evening_star", "bearish", _ctx(trend, "up", 0.8),
                          c.low, max(a.high, b.high, c.high))
    return None


def detect_patterns(candles: list[Candle]) -> list[PatternHit]:
    """All patterns visible on the most recent closed candle, strongest first."""
    if len(candles) < 3:
        return []
    a, b, c = candles[-3], candles[-2], candles[-1]
    trend = trend_of(candles)
    hits: list[PatternHit] = []
    for hit in (_star(a, b, c, trend), _engulfing(b, c, trend),
                _tweezers(b, c, trend), _hammer_star(c, trend),
                _harami(b, c, trend), _inside_bar(b, c), _doji(c, trend)):
        if hit is not None:
            hits.append(hit)
    return sorted(hits, key=lambda h: h.strength, reverse=True)


class CandlestickRule(Rule):
    """Signal-engine rule: fires the strongest fresh candlestick pattern."""
    name = "candlestick"
    cooldown_s = 1800   # one candle length — a pattern fires once

    def __init__(self, bucket_s: float = DEFAULT_BUCKET_S, min_strength: float = 0.45):
        self.bucket_s = bucket_s
        self.min_strength = min_strength

    def evaluate(self, coin: Coin, quote: Quote, history: list[dict]):
        from .. import clock
        candles = closed_candles(build_candles(history, self.bucket_s),
                                 clock.now(), self.bucket_s)
        if len(candles) < 12:   # need real context before trusting a pattern
            return None
        hits = [h for h in detect_patterns(candles)
                if h.direction != "neutral" and h.strength >= self.min_strength]
        if not hits:
            return None
        top = hits[0]
        return SignalHit(rule=self.name, direction=top.direction,
                         strength=top.strength,
                         details={"pattern": top.name,
                                  "trend": trend_of(candles),
                                  "stop_anchor": top.candle_low if
                                  top.direction == "bullish" else top.candle_high})

cryptodeck/signals/rules.py:
"""Rule-based signals — free 'smart maths' that runs constantly.
Each rule evaluates one coin against its recent snapshot history
(list of dicts: ts, price_usd, volume_24h, liquidity_usd).
"""
from __future__ import annotations

import time
from abc import ABC, abstractmethod
from dataclasses import dataclass

from ..models import Coin, Quote


@dataclass(frozen=True)
class SignalHit:
    rule: str
    direction: str        # bullish | bearish | risk
    strength: float       # 0..1
    details: dict


class Rule(ABC):
    name: str = "rule"
    cooldown_s: int = 900

    @abstractmethod
    def evaluate(self, coin: Coin, quote: Quote,
                 history: list[dict]) -> SignalHit | None: ...


def _window(history: list[dict], minutes: float) -> list[dict]:
    cutoff = time.time() - minutes * 60
    return [h for h in history if h["ts"] >= cutoff]


class MomentumRule(Rule):
    """Price moved sharply within 15m/1h windows."""
    name = "momentum"
    cooldown_s = 1800

    def __init__(self, threshold_pct_15m: float = 2.0, threshold_pct_1h: float = 4.0):
        self.thresholds = ((15, threshold_pct_15m), (60, threshold_pct_1h))

    def evaluate(self, coin, quote, history):
        for minutes, threshold in self.thresholds:
            w = _window(history, minutes)
            if len(w) < 2 or w[0]["price_usd"] <= 0:
                continue
            chg = (quote.price_usd / w[0]["price_usd"] - 1) * 100
            if abs(chg) >= threshold:
                return SignalHit(
                    rule=self.name,
                    direction="bullish" if chg > 0 else "bearish",
                    strength=min(1.0, abs(chg) / (threshold * 3)),
                    details={"window_min": minutes, "change_pct": round(chg, 2)})
        return None


class VolumeSpikeRule(Rule):
    """Reported 24h volume jumped vs its trailing 6h mean."""
    name = "volume_spike"
    cooldown_s = 3600

    def __init__(self, spike_ratio: float = 1.5):
        self.spike_ratio = spike_ratio

    def evaluate(self, coin, quote, history):
        if not quote.volume_24h:
            return None
        vols = [h["volume_24h"] for h in _window(history, 360)
                if h.get("volume_24h")]
        if len(vols) < 5:
            return None
        mean = sum(vols) / len(vols)
        if mean <= 0:
            return None
        ratio = quote.volume_24h / mean
        if ratio >= self.spike_ratio:
            return SignalHit(
                rule=self.name, direction="bullish",
                strength=min(1.0, (ratio - 1) / (self.spike_ratio * 2)),
                details={"volume_ratio": round(ratio, 2),
                         "volume_24h": quote.volume_24h})
        return None


class LiquidityDropRule(Rule):
    """DEX pair liquidity fell hard — rug early-warning. Risk, not trade advice."""
    name = "liquidity_drop"
    cooldown_s = 1800

    def __init__(self, drop_pct: float = 30.0):
        self.drop_pct = drop_pct

    def evaluate(self, coin, quote, history):
        if coin.source != "dexscreener" or not quote.liquidity_usd:
            return None
        liqs = [h["liquidity_usd"] for h in _window(history, 360)
                if h.get("liquidity_usd")]
        if len(liqs) < 3:
            return None
        peak = max(liqs)
        if peak <= 0:
            return None
        drop = (1 - quote.liquidity_usd / peak) * 100
        if drop >= self.drop_pct:
            return SignalHit(
                rule=self.name, direction="risk",
                strength=min(1.0, drop / 100),
                details={"liquidity_drop_pct": round(drop, 1),
                         "liquidity_now": quote.liquidity_usd, "liquidity_peak": peak})
        return None


def default_rules() -> list[Rule]:
    from .candles import CandlestickRule  # local import: candles.py imports Rule
    return [MomentumRule(), VolumeSpikeRule(), LiquidityDropRule(),
            CandlestickRule()]

cryptodeck/strategies/exits.py:
"""Shared exit decisions — the tier/trailing/stop logic from SolSniper's
exit_manager, as a pure function. Strategies decide; StrategyContext executes.
"""
from __future__ import annotations

from .. import clock
from dataclasses import dataclass

from ..models import Position, Quote


@dataclass(frozen=True)
class ExitParams:
    stop_loss_pct: float = -20.0        # hard stop vs entry
    take_profit_pct: float = 50.0       # sell half here (tiered)
    trailing_stop_pct: float = 15.0     # drop from peak after TP tier
    max_hold_hours: float = 72.0


@dataclass(frozen=True)
class ExitDecision:
    reason: str
    fraction: float                     # 1.0 = close all, 0.5 = sell half


def check_exit(pos: Position, quote: Quote, p: ExitParams,
               half_sold: bool) -> ExitDecision | None:
    """Return an exit decision, or None to keep holding."""
    if pos.avg_entry_price <= 0:
        return None
    pnl_pct = (quote.price_usd / pos.avg_entry_price - 1) * 100

    if pnl_pct <= p.stop_loss_pct:
        return ExitDecision(f"stop loss {pnl_pct:.1f}%", 1.0)

    if clock.now() - pos.opened_at > p.max_hold_hours * 3600:
        return ExitDecision(f"max hold {p.max_hold_hours:.0f}h", 1.0)

    if not half_sold and pnl_pct >= p.take_profit_pct:
        return ExitDecision(f"take profit tier +{pnl_pct:.1f}%", 0.5)

    if half_sold and pos.peak_price:
        drop_pct = (1 - quote.price_usd / pos.peak_price) * 100
        if drop_pct >= p.trailing_stop_pct:
            return ExitDecision(f"trailing stop -{drop_pct:.1f}% from peak", 1.0)

    return None

cryptodeck/strategies/rebalancer.py:
"""The sensible adult: hold BTC 60% / ETH 30% / SOL 10% and rebalance daily
when any leg drifts. No stops, no signals — the allocation IS the strategy.
"""
from __future__ import annotations

from .. import clock
from .base import Strategy, StrategyContext


class Rebalancer(Strategy):
    name = "rebalancer"
    description = "Holds BTC 60/ETH 30/SOL 10 and rebalances daily on drift"
    tick_interval_s = 300.0
    default_params = {
        "targets": {"bitcoin": 60.0, "ethereum": 30.0, "solana": 10.0},  # % of equity
        "interval_hours": 24.0,
        "drift_pct_of_equity": 2.0,   # act when a leg is off by more than this
        "max_single_order_usd": 400.0,  # stay under the exchange's order cap
        "breaker_pct": 10,            # allocation bots only halt on catastrophe
    }

    async def on_tick(self, ctx: StrategyContext) -> None:
        p = ctx.params
        last = float(ctx.db.get_setting(f"bot.{self.name}.last_rebalance_ts", "0"))
        if clock.now() - last < float(p["interval_hours"]) * 3600:
            return

        coins = {c.source_id: c for c in ctx.db.list_coins()
                 if c.source == "coingecko" and c.source_id in p["targets"]}
        if len(coins) < len(p["targets"]):
            return
        quotes = {gid: ctx.hub.get_quote(c.id) for gid, c in coins.items()}
        if any(q is None for q in quotes.values()):
            return  # rebalance only with full price data

        positions = {pos.coin_id: pos for pos in ctx.positions() if pos.status == "open"}
        wallet = ctx.wallet
        holdings = {gid: (positions.get(c.id).qty * quotes[gid].price_usd
                          if c.id in positions else 0.0)
                    for gid, c in coins.items()}
        equity = wallet.balance + sum(holdings.values())
        if equity <= 0:
            return

        threshold = equity * float(p["drift_pct_of_equity"]) / 100
        acted = False
        # sells first so the freed cash can fund the buys
        for phase in ("sell", "buy"):
            for gid, coin in coins.items():
                target_usd = equity * float(p["targets"][gid]) / 100
                diff = target_usd - holdings[gid]     # +ve: underweight, buy
                if abs(diff) < threshold:
                    continue
                if phase == "sell" and diff < 0 and coin.id in positions:
                    qty = min(positions[coin.id].qty,
                              -diff / quotes[gid].price_usd)
                    res = await ctx.sell(coin, qty, reason="rebalance")
                    acted = acted or res.filled
                elif phase == "buy" and diff > 0:
                    remaining = min(diff, ctx.wallet.balance * 0.98)
                    chunk_cap = float(p["max_single_order_usd"])
                    for _ in range(4):  # chunked to respect the order cap
                        spend = min(remaining, chunk_cap)
                        if spend < 1.0:
                            break
                        res = await ctx.buy(coin, spend)
                        if not res.filled:
                            break
                        acted = True
                        remaining = min(remaining - spend, ctx.wallet.balance * 0.98)
        if acted:
            ctx.log("rebalanced toward BTC 60 / ETH 30 / SOL 10")
        ctx.db.set_setting(f"bot.{self.name}.last_rebalance_ts", str(clock.now()))

cryptodeck/sweep.py:
"""War Games: grid-search a strategy's parameters through BacktestRunner and
report return_pct per cell. A curated allow-list, not an open "sweep any
param" surface — keeps the grid small and the runtime bounded.
"""
from __future__ import annotations

import itertools
import time
import uuid
from typing import Any

SWEEP_GRIDS: dict[str, dict[str, list[float]]] = {
    "rsi_oscillator": {
        "buy_below": [20.0, 25.0, 30.0, 35.0, 40.0],
        "sell_above": [60.0, 65.0, 70.0, 75.0, 80.0],
    },
    "candlestick_trader": {
        "risk_pct_of_equity": [0.5, 1.0, 1.5, 2.0, 2.5],
        "reward_risk_ratio": [1.5, 2.0, 2.5, 3.0, 3.5],
    },
}
MAX_SWEEP_CELLS = 30
JOB_TTL_S = 3600
MAX_JOBS_KEPT = 5


class SweepRunner:
    def __init__(self, backtester):
        self.backtester = backtester
        self._jobs: dict[str, dict[str, Any]] = {}

    def _evict_stale(self) -> None:
        now = time.time()
        stale = [jid for jid, j in self._jobs.items()
                 if now - j["started_at"] > JOB_TTL_S]
        for jid in stale:
            del self._jobs[jid]
        while len(self._jobs) > MAX_JOBS_KEPT:
            oldest = min(self._jobs, key=lambda jid: self._jobs[jid]["started_at"])
            del self._jobs[oldest]

    def _running_job(self) -> str | None:
        for jid, j in self._jobs.items():
            if j["status"] == "running":
                return jid
        return None

    def start(self, strategy_name: str, hours: float) -> dict:
        self._evict_stale()
        if self._running_job() is not None:
            return {"error": "a sweep is already running — wait for it to finish"}
        grid = SWEEP_GRIDS.get(strategy_name)
        if grid is None:
            return {"error": f"'{strategy_name}' has no sweep grid defined"}
        keys = list(grid.keys())
        cells = list(itertools.product(*(grid[k] for k in keys)))
        if len(cells) > MAX_SWEEP_CELLS:
            return {"error": f"grid too large ({len(cells)} cells, max {MAX_SWEEP_CELLS})"}
        job_id = uuid.uuid4().hex
        self._jobs[job_id] = {
            "status": "running",
            "started_at": time.time(),
            "strategy": strategy_name,
            "keys": keys,
            "progress": {"done": 0, "total": len(cells)},
            "results": [],
            "_pending": [dict(zip(keys, cell)) for cell in cells],
            "hours": hours,
        }
        return {"job_id": job_id}

    async def run_job(self, job_id: str) -> None:
        import asyncio

        job = self._jobs.get(job_id)
        if job is None:
            return
        try:
            for cell_params in job["_pending"]:
                result = await asyncio.to_thread(
                    self.backtester.run, job["strategy"], job["hours"], cell_params)
                if "error" in result:
                    job["results"].append({"params": cell_params, "error": result["error"]})
                else:
                    job["results"].append({"params": cell_params, **result["stats"]})
                job["progress"]["done"] += 1
            job["status"] = "done"
        except Exception as e:   # crash isolation — surface it, don't hang the job forever
            job["status"] = "error"
            job["error"] = f"{type(e).__name__}: {e}"
        finally:
            job.pop("_pending", None)

    def status(self, job_id: str) -> dict:
        job = self._jobs.get(job_id)
        if job is None:
            return {"error": "unknown job_id"}
        return {"status": job["status"], "progress": job["progress"],
                "results": job["results"], "keys": job["keys"]}

cryptodeck/trading/exchange.py:
"""ExchangeAdapter interface and PaperExchange — the ONLY implementation.

There is deliberately no live adapter, no key handling, and no signing code
anywhere in this codebase. PaperExchange fills orders at real live prices with
a slippage + fee model against simulated wallet balances.

Orders are one-shot: execute() always returns a definitively `filled` or
`rejected` result before the caller sees anything. There is no 'pending'
escape hatch and no retry loop — the two failure modes that wrecked SolSniper.
"""
from __future__ import annotations

import time
from abc import ABC, abstractmethod

from ..config import Settings
from ..data.hub import DataHub
from ..db import Database
from ..models import Coin, OrderRequest, OrderResult
from .portfolio import Portfolio


class ExchangeAdapter(ABC):
    @abstractmethod
    async def execute(self, req: OrderRequest) -> OrderResult: ...

    @abstractmethod
    async def get_fill_price(self, coin: Coin, side: str) -> float | None: ...


class PaperExchange(ExchangeAdapter):
    def __init__(self, db: Database, hub: DataHub, portfolio: Portfolio, cfg: Settings):
        self.db = db
        self.hub = hub
        self.portfolio = portfolio
        self.cfg = cfg

    def _slippage_bps(self, coin: Coin, quote) -> int:
        if coin.chain == "majors":
            return self.cfg.slippage_bps
        # Thin DEX pairs: scale slippage with (implied) size vs liquidity, capped.
        liq = quote.liquidity_usd or 0
        if liq <= 0:
            return self.cfg.meme_slippage_bps
        return min(self.cfg.meme_slippage_bps,
                   max(self.cfg.slippage_bps, int(1e4 * 100 / liq)))

    async def get_fill_price(self, coin: Coin, side: str) -> float | None:
        q = await self.hub.fetch_quote(coin)
        if q is None or q.price_usd <= 0:
            return None
        slip = self._slippage_bps(coin, q) / 10_000
        return q.price_usd * (1 + slip) if side == "buy" else q.price_usd * (1 - slip)

    async def execute(self, req: OrderRequest) -> OrderResult:
        now = time.time()
        cur = self.db.conn.execute(
            "INSERT INTO orders (wallet_id, coin_id, side, qty, quote_amount, status, "
            "created_at) VALUES (?,?,?,?,?,'pending',?)",
            (req.wallet_id, req.coin_id, req.side, req.qty, req.quote_amount, now))
        self.db.conn.commit()
        order_id = cur.lastrowid

        def reject(reason: str) -> OrderResult:
            self.db.conn.execute(
                "UPDATE orders SET status='rejected', reject_reason=?, resolved_at=? WHERE id=?",
                (reason, time.time(), order_id))
            self.db.conn.commit()
            return OrderResult(order_id=order_id, status="rejected", reject_reason=reason)

        coin = self.db.get_coin(req.coin_id)
        if coin is None:
            return reject("unknown coin")

        quote = await self.hub.fetch_quote(coin)
        if quote is None or quote.price_usd <= 0:
            return reject("no fresh price — refusing to fill blind")

        slip_bps = self._slippage_bps(coin, quote)
        slip = slip_bps / 10_000
        fee_rate = self.cfg.fee_bps / 10_000

        wallet = self.db.get_wallet_by_id(req.wallet_id)
        if wallet is None:
            return reject("unknown wallet")

        if req.side == "buy":
            usd = req.quote_amount or 0.0
            if usd < self.cfg.min_order_usd:
                return reject(f"below min order ${self.cfg.min_order_usd:.2f}")
            if usd > self.cfg.max_order_usd:
                return reject(f"above max order cap ${self.cfg.max_order_usd:.2f}")
            fill_price = quote.price_usd * (1 + slip)
            fee = usd * fee_rate
            if wallet.balance < usd + fee:
                return reject(f"insufficient balance (${wallet.balance:.2f})")
            qty = usd / fill_price
        else:
            open_pos = [p for p in self.db.open_positions(req.wallet_id)
                        if p.coin_id == req.coin_id]
            if not open_pos:
                return reject("no open position")
            pos = open_pos[0]
            qty = req.qty if req.qty is not None else pos.qty
            if qty <= 0 or qty > pos.qty + 1e-12:
                return reject("sell qty exceeds position")
            fill_price = quote.price_usd * (1 - slip)
            fee = qty * fill_price * fee_rate

        try:
            position = self.portfolio.apply_fill(
                order_id=order_id, wallet_id=req.wallet_id, coin_id=req.coin_id,
                side=req.side, qty=qty, fill_price=fill_price, fee_usd=fee,
                close_reason=req.reason)
        except ValueError as e:
            return reject(str(e))

        self.db.conn.execute("UPDATE orders SET requested_price=?, slippage_bps=? WHERE id=?",
                             (quote.price_usd, slip_bps, order_id))
        self.db.conn.commit()
        return OrderResult(order_id=order_id, status="filled", fill_price=fill_price,
                           qty=qty, fee_usd=fee, position_id=position.id)
